"""Command-line parsing, input selection, and library configuration handling."""
import fnmatch
import json
import os
import re
import shlex
import signal
import sys
import xml.etree.ElementTree as ET
from dataclasses import dataclass, field

SHARE = '/usr/local/share/Cppcheck'
SUFFIXES = {'.c', '.cpp', '.cxx', '.cc', '.c++', '.ipp', '.ixx', '.tpp', '.txx'}

def out(text):
    sys.stdout.write(text + '\n')

def fail(text):
    out('cppcheck: error: ' + text)
    raise SystemExit(1)

def norm(path):
    return os.path.normpath(path.replace('\\', '/')) if path else ''

def integer(text, option, unsigned=False):
    reason = None
    if not re.fullmatch(r'\s*[+-]?\d+', text, re.ASCII):
        reason = 'not an integer'
    elif unsigned and text.lstrip().startswith('-'):
        reason = 'needs to be positive'
    else:
        n = int(text)
        if n < -2**63 or n >= (2**64 if unsigned else 2**63):
            reason = 'out of range (' + ('stoull' if unsigned else 'stoll') + ')'
        elif n < (0 if unsigned else -2**31) or n > (2**32-1 if unsigned else 2**31-1):
            reason = 'out of range (limits)'
    if reason:
        fail("argument to '%s' is not valid - %s." % (option, reason))
    return n


def xml_error(text, exc=None):
    if not text.strip() or text.lstrip().startswith('<!--') and '-->' in text and not text.split('-->',1)[1].strip():
        return ('XML_ERROR_EMPTY_DOCUMENT', 13, 0, '')
    if not text.lstrip().startswith('<'):
        return ('XML_ERROR_PARSING_TEXT', 8, 1, '')
    m = re.search(r'<([A-Za-z_][\w:.-]*)(?:\s|>)', text)
    name = m.group(1) if m else ''
    if 'mismatched tag' in str(exc) or name and not re.search(r'</'+re.escape(name)+r'\s*>', text) and not re.search(r'<'+re.escape(name)+r'[^>]*?/>', text):
        line = text[:m.start()].count('\n') + 1 if m else 1
        return ('XML_ERROR_MISMATCHED_ELEMENT',14,line,': XMLElement name='+name)
    if text.lstrip().startswith('<?'):
        return ('XML_ERROR_PARSING_DECLARATION',11,1,'')
    return ('XML_ERROR_PARSING',15,1,'')

@dataclass
class Suppression:
    id: str
    file: str = ''
    line: int = -1
    matched: bool = False
    symbol: str = ''
    def key(self):
        return (self.id, self.file, self.line, self.symbol)
    def text(self):
        return self.id + (':' + self.file if self.file else '') + (':' + str(self.line) if self.line != -1 else '')
    def matches(self, diagnostic):
        return (fnmatch.fnmatchcase(diagnostic.id, self.id)
                and (not self.file or fnmatch.fnmatchcase(diagnostic.file, self.file))
                and (self.line < 0 or self.line == diagnostic.line))

def add_suppression(text, destination):
    parts = text.split(':')
    errorid = parts[0]
    if not errorid:
        fail('Failed to add suppression. No id.')
    if not re.fullmatch(r'[A-Za-z_*][A-Za-z_0-9.*-]*', errorid):
        fail('Failed to add suppression. Invalid id "' + errorid + '"')
    filename, line = '', -1
    if len(parts) > 1:
        rest = ':'.join(parts[1:])
        if len(parts) > 2 and re.fullmatch(r'-?\d+', parts[-1]):
            filename, line = ':'.join(parts[1:-1]), int(parts[-1])
        else:
            filename = rest
        filename = norm(filename)
    s = Suppression(errorid, filename, line)
    if any(x.key() == s.key() for x in destination):
        fail("suppression '%s' already exists" % s.text())
    destination.append(s)

@dataclass
class Options:
    bindir: str
    files: list = field(default_factory=list)
    project_files: list = field(default_factory=list)
    project: str = ''
    project_seen: bool = False
    project_type: str = ''
    configurations: list = field(default_factory=list)
    enabled: set = field(default_factory=set)
    includes: list = field(default_factory=list)
    include_files: list = field(default_factory=list)
    defines: list = field(default_factory=list)
    undefines: list = field(default_factory=list)
    ignores: list = field(default_factory=list)
    filters: list = field(default_factory=list)
    filter_plus: bool = False
    libraries: list = field(default_factory=list)
    suppressions: list = field(default_factory=list)
    exit_suppressions: list = field(default_factory=list)
    addons: list = field(default_factory=list)
    addon_python: str = ''
    flags: set = field(default_factory=set)
    jobs: int = 1
    error_exitcode: int = 0
    max_configs: int = 12
    max_ctu_depth: int = 2
    executor: str = ''
    platform: str = 'native'
    std_c: str = 'c11'
    std_cpp: str = 'c++20'
    language: str = ''
    output_format: str = 'text'
    output_set: bool = False
    xml_set: bool = False
    xml_version: int = 2
    template: str = 'gcc'
    template_location: str = ''
    output_file: str = ''
    build_dir: str = ''
    no_build_dir: bool = False
    plist: str = ''
    checkers_report: str = ''
    relative: bool = False
    bases: list = field(default_factory=list)
    showtime: str = 'none'
    report_type: str = 'normal'
    check_level: str = 'normal'
    clang: str = ''
    critical: bool = False
    library_roots: list = field(default_factory=list)

    def flag(self, name):
        return name in self.flags

    def enable(self, value, disable=False):
        opt = '--disable' if disable else '--enable'
        if not value:
            fail(opt + ' parameter is empty')
        for item in value.split(','):
            if not item:
                fail(opt + '--enable parameter is empty')
            groups = {
                'all': {'warning','style','performance','portability','information','unusedFunction','missingInclude'},
                'style': {'style','warning','performance','portability'},
            }
            if item not in ('all','style','warning','performance','portability','information','unusedFunction','missingInclude'):
                fail(opt + " parameter with the unknown name '" + item + "'")
            vals = groups.get(item, {item})
            if disable:
                self.enabled.difference_update(vals)
            else:
                self.enabled.update(vals)

    def read_lines(self, path, mode):
        if path == '-' and mode in ('--file-list','--file-filter'):
            return sys.stdin.read().splitlines()
        try:
            with open(path, 'r', errors='replace') as f:
                return f.read().splitlines()
        except OSError:
            if mode == '--includes-file':
                fail("unable to open includes file at '%s'" % path)
            if mode == '--config-excludes-file':
                fail("unable to open config excludes file at '%s'" % path)
            fail('couldn\'t open the file: "' + path + '".')

    def load_project(self, path):
        if self.project_seen:
            fail('multiple --project options are not supported.')
        if self.files:
            fail('--project cannot be used in conjunction with source files.')
        self.project, self.project_seen = path, True
        try:
            text = open(path, errors='replace').read()
        except (OSError, ValueError):
            fail("failed to open project '%s'. The file does not exist." % path)
        ext = os.path.splitext(path)[1]
        self.project_type = ext
        def project_error(detail):
            if detail:
                out('cppcheck: error: ' + detail)
            fail("failed to load project '%s'. An error occurred." % path)
        if ext == '.json':
            try:
                database = json.loads(text)
            except (ValueError, TypeError):
                database = None
            if not isinstance(database, list):
                project_error('compilation database is not a JSON array')
            for entry in database:
                if not isinstance(entry, dict):
                    self.abort_type('object')
                for name in ('directory',):
                    if name not in entry:
                        project_error("'%s' field in compilation database entry missing" % name)
                    if not isinstance(entry[name],str):
                        project_error("'%s' field in compilation database entry is not a string" % name)
                if 'arguments' not in entry and 'command' not in entry:
                    project_error("no 'arguments' or 'command' field found in compilation database entry")
                if 'arguments' in entry:
                    if not isinstance(entry['arguments'],list):
                        project_error("'arguments' field in compilation database entry is not an array")
                    args = entry['arguments']
                else:
                    if not isinstance(entry['command'],str):
                        project_error("'command' field in compilation database entry is not a string")
                    try:
                        args = shlex.split(entry['command'])
                    except ValueError:
                        args = entry['command'].split()
                if 'file' not in entry:
                    project_error("'file' field in compilation database entry missing")
                if not isinstance(entry['file'],str):
                    project_error("'file' field in compilation database entry is not a string")
                filename = entry['file']
                if os.path.splitext(filename)[1].lower() not in SUFFIXES:
                    continue
                d = entry['directory']
                if not os.path.isabs(d):
                    d = os.path.join(os.path.dirname(path), d)
                filename = norm(os.path.join(d, filename))
                if not os.path.isfile(filename):
                    out("cppcheck: warning: '%s' from compilation database does not exist" % filename)
                    continue
                self.project_files.append((filename,args))
        elif ext in ('.cppcheck', '.vcxproj', '.bpr'):
            try:
                root = ET.fromstring(text)
            except ET.ParseError as e:
                desc = xml_error(text,e)[0]
                if ext == '.cppcheck':
                    project_error('Cppcheck GUI project file is not a valid XML - ' + desc)
                else:
                    project_error('')
            if ext == '.cppcheck':
                for elm in root.findall('./paths/dir'):
                    name = elm.get('name','')
                    self.project_files.append((norm(os.path.join(os.path.dirname(path),name)),[]))
                for elm in root.findall('./includedir/dir'):
                    self.includes.append(norm(os.path.join(os.path.dirname(path),elm.get('name',''))))
                for elm in root.findall('./defines/define'):
                    self.defines.append(elm.get('name',''))
                for elm in root.findall('./libraries/library'):
                    if elm.text: self.libraries.append(elm.text)
                for elm in root.findall('./exclude/path'):
                    self.ignores.append(norm(os.path.join(os.path.dirname(path),elm.get('name',''))))
            else:
                for elm in root.iter():
                    if elm.tag.rsplit('}',1)[-1] in ('ClCompile','FILE'):
                        name = elm.get('Include',elm.get('FILENAME',''))
                        if name:
                            self.project_files.append((norm(os.path.join(os.path.dirname(path),name)),[]))
        elif ext == '.sln':
            for name in re.findall(r'"([^"\n]+\.vcxproj)"',text):
                pp = norm(os.path.join(os.path.dirname(path), name))
                if os.path.isfile(pp):
                    try:
                        root=ET.parse(pp).getroot()
                        for elm in root.iter():
                            if elm.tag.rsplit('}',1)[-1]=='ClCompile' and elm.get('Include'):
                                self.project_files.append((norm(os.path.join(os.path.dirname(pp),elm.get('Include'))),[]))
                    except ET.ParseError:
                        pass
        else:
            fail("failed to load project '%s'. The format is unknown." % path)

    @staticmethod
    def abort_type(kind):
        sys.stderr.write('terminate called after throwing an instance of \'std::runtime_error\'\n  what():  "type mismatch! call is<type>() before get<type>()" && is<'+kind+'>()\n')
        sys.stderr.flush()
        try:
            import resource
            resource.setrlimit(resource.RLIMIT_CORE, (0,0))
        except (ImportError, ValueError):
            pass
        os.kill(os.getpid(),signal.SIGABRT)

    def parse(self, args):
        flags = {'--check-config','--check-library','--inconclusive','--inline-suppr','--safety','--fsigned-char','--funsigned-char','--dump','--debug','--debug-normal','--debug-simplified','--debug-template','--debug-warnings','--debug-valueflow','--debug-ast','--debug-lookup','--debug-clang-output','--clang-tidy'}
        numeric = {'--max-configs','--max-ctu-depth','--error-exitcode','--max-template-recursion','--template-max-time','--xml-version','--report-progress'}
        string_flags = {'--config-exclude','--include','--addon','--addon-python','--output-file','--checkers-report','--template','--template-location','--clang'}
        i = 0
        while i < len(args):
            arg=args[i]; i+=1
            if arg in flags:
                self.flags.add(arg[2:]); continue
            if arg in ('--quiet','-q'):
                self.flags.add('quiet'); continue
            if arg in ('--verbose','-v'):
                self.flags.add('verbose'); continue
            if arg in ('--force','-f'):
                self.flags.add('force'); self.max_configs=2**31-1; continue
            if arg=='-E':
                self.flags.add('preprocess'); continue
            if arg=='--report-progress':
                self.flags.add('report-progress'); continue
            if arg=='--clang':
                self.clang='clang'; continue
            if arg=='--exception-handling':
                self.flags.add('exception-handling'); continue
            if arg in ('--relative-paths','-rp'):
                self.relative=True; continue
            if arg=='--no-cppcheck-build-dir':
                self.no_build_dir=True; continue
            if arg=='--xml':
                if self.output_set:
                    fail("'--output-format' and '--xml...' may not be used in conjunction.")
                self.xml_set=True; self.output_format='xmlv'+str(self.xml_version); continue
            if len(arg)>=2 and arg[:2] in ('-I','-D','-U','-i','-j','-l'):
                short=arg[:2]; value=arg[2:]
                if len(arg)==2:
                    if i==len(args) or args[i].startswith('-'):
                        fail("argument to '%s' is missing." % short)
                    value=args[i]; i+=1
                if short=='-j':
                    self.jobs=integer(value,short,True)
                    if self.jobs==0: fail("argument for '-j' must be greater than 0.")
                    if self.jobs>1024: fail("argument for '-j' is allowed to be 1024 at max.")
                elif short=='-l': integer(value,short)
                elif short=='-I': self.includes.append(norm(value))
                elif short=='-D': self.defines.extend(value.split(';') if value else [])
                elif short=='-U': self.undefines.append(value)
                elif short=='-i': self.ignores.append(norm(value))
                continue
            if arg=='-x':
                if i==len(args) or args[i].startswith('-'):
                    fail("no language given to '-x' option.")
                arg='--language='+args[i]; i+=1
            key, eq, value = arg.partition('=')
            if eq:
                if key in ('--enable','--disable'):
                    self.enable(value, key=='--disable'); continue
                if key=='--language':
                    if value not in ('c','c++'): fail("unknown language '%s' enforced." % value)
                    self.language=value; continue
                if key=='--std':
                    c={'89':'89','90':'89','99':'99','9x':'99','11':'11','1x':'11','17':'17','18':'17','2x':'23','23':'23','2y':'26','26':'26'}
                    cpp={'03':'03','98':'03','0x':'11','11':'11','1y':'14','14':'14','1z':'17','17':'17','2a':'20','20':'20','2b':'23','23':'23','2c':'26','26':'26'}
                    m=re.fullmatch(r'(c\+\+|gnu\+\+)(.*)',value)
