                        else: fail("unknown --std value '%s'" % value)
                    continue
                if key in numeric:
                    if key=='--xml-version' and self.output_set:
                        fail("'--output-format' and '--xml...' may not be used in conjunction.")
                    n=integer(value,key+'=', key=='--template-max-time')
                    if key=='--xml-version':
                        if n not in (2,3): fail("'--xml-version' can only be 2 or 3.")
                        self.xml_version=n; self.xml_set=True; self.output_format='xmlv'+str(n)
                    elif key=='--max-configs':
