                        self.max_configs=n; self.flags.discard('force')
                    elif key=='--report-progress':
                        if n<0: fail("argument to '--report-progress=' needs to be a positive integer.")
                        self.flags.add('report-progress')
                    elif key=='--error-exitcode': self.error_exitcode=n
                    elif key=='--max-ctu-depth': self.max_ctu_depth=n
                    continue
                if key=='--library':
                    if any(not p for p in value.split(',')): fail('empty library specified.')
                    self.libraries.extend(value.split(',')); continue
                if key=='--platform':
                    if not value: fail('empty platform specified.')
                    self.platform=value; continue
                if key=='--suppress':
                    add_suppression(value,self.suppressions); continue
                if key in ('--suppressions-list','--exitcode-suppressions'):
                    dest=self.suppressions if key=='--suppressions-list' else self.exit_suppressions
                    for line in self.read_lines(value,key):
                        line=line.strip()
                        if line and not line.startswith(('#','//')): add_suppression(line,dest)
                    continue
                if key=='--suppress-xml':
                    try:
                        text=open(value,errors='replace').read()
                    except (OSError,ValueError):
                        fail("failed to load suppressions XML '%s' (XML_ERROR_FILE_NOT_FOUND)." % value)
                    try:
                        root=ET.fromstring(text)
                    except ET.ParseError as e:
                        fail("failed to load suppressions XML '%s' (%s)." % (value,xml_error(text,e)[0]))
                    for s in root.findall('suppress'):
                        eid=s.findtext('id','')
                        filename=s.findtext('fileName','')
                        line=s.findtext('lineNumber','')
                        add_suppression(eid+(':'+filename if filename or line else '')+(':'+line if line else ''),self.suppressions)
                    continue
                if key in ('--file-list','--file-filter','--includes-file','--config-excludes-file'):
                    if key=='--file-filter':
                        if value=='+': self.filter_plus=True
                        elif value=='-': self.filters.extend(self.read_lines(value,key))
                        else: self.filters.append(value)
                    else:
                        lines=self.read_lines(value,key)
                        if key=='--file-list':
                            if self.project_seen and any(lines): fail('--project cannot be used in conjunction with source files.')
                            self.files.extend(line for line in lines if line)
                        elif key=='--includes-file': self.includes.extend(norm(x) for x in lines if x)
                    continue
                if key=='--cppcheck-build-dir':
                    if not value: fail('no path has been specified for --cppcheck-build-dir')
                    self.build_dir=value; continue
                if key=='--plist-output':
                    if value and not os.path.isdir(value): fail("plist folder does not exist: '%s'." % value)
                    self.plist=value; continue
                if key=='--project': self.load_project(value); continue
                if key=='--project-configuration':
                    if not value: fail('--project-configuration parameter is empty.')
                    if self.project_type not in ('.sln','.vcxproj'):
                        fail('--project-configuration has no effect - no Visual Studio project provided.')
                    self.configurations.append(value); continue
                if key=='--output-format':
                    if self.xml_set: fail("'--output-format' and '--xml...' may not be used in conjunction.")
                    if value not in ('text','sarif','xml','xmlv2','xmlv3'):
                        fail("argument to '--output-format=' must be 'text', 'sarif', 'xml' (deprecated), 'xmlv2' or 'xmlv3'.")
                    self.output_format='xmlv2' if value=='xml' else value
                    self.output_set=True; continue
                if key=='--check-level':
                    if value not in ('reduced','normal','exhaustive'): fail("unknown '--check-level' value '%s'." % value)
                    self.check_level=value; continue
                if key=='--showtime':
                    if value not in ('none','file','file-total','summary','top5_file','top5_summary'):
                        fail("unrecognized --showtime mode: '%s'. Supported modes: file, file-total, summary, top5_file, top5_summary." % value)
                    self.showtime=value; continue
                if key=='--report-type':
                    if value not in ('normal','autosar','cert-c-2016','cert-cpp-2016','misra-c-2012','misra-c-2023','misra-c-2025','misra-cpp-2008','misra-cpp-2023'):
                        fail("Unknown report type '%s'" % value)
                    self.report_type=value; continue
                if key=='--executor':
                    if value not in ('thread','process'): fail("unknown executor: '%s'." % value)
                    self.executor=value; continue
                if key=='--exception-handling':
                    if value not in ('stdout','stderr'): fail("invalid '--exception-handling' argument")
                    self.flags.add('exception-handling'); continue
                if key in ('-rp','--relative-paths'):
                    if not value: fail("no paths specified for the '%s=' option." % key)
                    self.relative=True; self.bases.extend(norm(p) for p in value.split(';') if p); continue
                if key in ('--rule','--rule-file'):
                    fail('Option '+key+' cannot be used as Cppcheck has not been built with rules support.')
                if key in string_flags:
                    if key=='--include': self.include_files.append(value)
                    elif key=='--addon': self.addons.append(value)
                    elif key=='--config-exclude': pass
                    elif key=='--clang': self.clang=value or 'clang'
                    else: setattr(self,key[2:].replace('-','_'),value)
                    continue
            if arg.startswith('-'):
                fail('unrecognized command line option: "' + arg + '".')
            if self.project_seen:
                if self.filter_plus: self.filters.append(arg)
                else: fail('--project cannot be used in conjunction with source files.')
            else:
                self.files.append(arg)
        if self.no_build_dir: self.build_dir=''
        if self.build_dir and not os.path.isdir(self.build_dir):
            fail("Directory '%s' specified by --cppcheck-build-dir argument has to be existent." % self.build_dir)
        self.validate_platform()
        if self.executor and self.jobs==1:
            out("cppcheck: '--executor' has no effect as only a single job will be used.")
        if self.jobs>1 and 'unusedFunction' in self.enabled and not self.build_dir:
            out('cppcheck: unusedFunction check requires --cppcheck-build-dir to be active with -j.')
        if not self.files and not self.project_files:
            fail('no C or C++ source files found.')
        return self

    def validate_platform(self):
        if self.platform in ('native','unspecified','unix32','unix64','win32A','win32W','win64'):
            return
        value=self.platform
        debug=self.flag('debug-lookup')
        if debug: out("looking for platform '%s'" % value)
        name=value if value.endswith('.xml') else value+'.xml'
        candidates=[os.path.join(os.getcwd(),name),os.path.join(os.getcwd(),'platforms',name),os.path.join(self.bindir,name),os.path.join(self.bindir,'platforms',name),os.path.join(SHARE,'platforms',name)]
        for p in candidates:
            p=norm(p)
            if debug:
                sys.stdout.write("try to load platform file '%s' ... " % p)
            try:
                root=ET.parse(p).getroot()
                if debug: out('success')
                if root.tag=='platform': return
            except OSError:
                if debug: out('Error=XML_ERROR_FILE_NOT_FOUND ErrorID=3 (0x3) Line number=0: filename='+p)
            except ET.ParseError:
                if debug: out('failed')
        fail("unrecognized platform: '%s'." % value)

    def display_path(self,path):
        path=norm(path)
        if self.relative:
            bases=self.bases or [norm(p) for p in self.files]
            for base in bases:
                if path.startswith(base.rstrip('/')+'/'):
                    return path[len(base.rstrip('/'))+1:]
        return path

    def load_libraries(self):
        for name in ['std.cfg']+self.libraries:
            ok=self.load_library(name)
            if not ok:
                if name=='std.cfg':
                    out('Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. The Cppcheck binary was compiled with FILESDIR set to "'+SHARE+'" and will therefore search for std.cfg in '+SHARE+'/cfg.')
                raise SystemExit(1)

    def load_library(self,name):
        suffix=name if os.path.splitext(name)[1] else name+'.cfg'
        candidates=[suffix,os.path.join(self.bindir,suffix),os.path.join(self.bindir,'cfg',suffix),os.path.join(SHARE,'cfg',suffix)]
        debug=self.flag('debug-lookup')
        reason='File not found'; text=None
        for path in candidates:
            if debug: out("looking for library '%s'" % path)
            try:
                text=open(path,errors='replace').read()
                break
            except (OSError,ValueError):
                pass
        if text is None:
            if debug: out("library not found: '%s'" % name)
        else:
            try:
                root=ET.fromstring(text)
            except ET.ParseError as e:
                e_name,e_id,line,extra=xml_error(text,e)
                out('Error=%s ErrorID=%d (0x%x) Line number=%d%s' % (e_name,e_id,e_id,line,extra))
                reason='Bad XML'
            else:
                if root.tag!='def':
                    reason="File is of unsupported format version '%s'" % root.tag
                elif root.get('format','2') not in ('1','2'):
                    reason='File is of unsupported format version'
                else:
                    known={'memory','resource','function','define','platformtype','podtype','container','smart-pointer','markup','type-checks','reflection','entrypoint'}
                    unknown=sorted(set(c.tag for c in root if c.tag not in known))
                    if unknown: out("cppcheck: Found unknown elements in configuration file '%s': %s" % (name, ', '.join(unknown)))
                    self.library_roots.append(root)
                    return True
        out("cppcheck: Failed to load library configuration file '%s'. %s" % (name,reason))
        return False

    def collect_files(self):
        selected=[]
        raw=[(p,[]) for p in self.files]+self.project_files
        def ignored(p):
            p=norm(p)
            for x in self.ignores:
                if not x: continue
                x=norm(x)
                if p==x or p.startswith(x.rstrip('/')+'/') or fnmatch.fnmatchcase(p,x): return True
            return False
        for path,args in raw:
            path=norm(path)
            found=[]
            if os.path.isdir(path):
                for root, dirs, files in os.walk(path):
                    dirs[:]=sorted(d for d in dirs if not ignored(os.path.join(root,d)))
                    for f in sorted(files):
                        p=norm(os.path.join(root,f))
                        if os.path.splitext(f)[1].lower() in SUFFIXES and not ignored(p): found.append(p)
            elif os.path.isfile(path) and not ignored(path):
                if self.language or os.path.splitext(path)[1].lower() in SUFFIXES or os.path.splitext(path)[1].lower() in ('.h','.hpp','.hxx','.hh'):
                    found=[path]
            for p in found:
                if self.filters and not any(fnmatch.fnmatchcase(p,f) for f in self.filters): continue
                if not any(x[0]==p for x in selected): selected.append((p,args))
        selected.sort(key=lambda x:x[0])
        if not selected:
            if self.ignores:
                out('cppcheck: error: could not find or open any of the paths given.')
                out('cppcheck: Maybe all paths were ignored?')
                raise SystemExit(1)
            fail('could not find or open any of the paths given.')
        return selected
