            path=norm(path)
            found=[]
            if os.path.isdir(path):
                for root, dirs, files in os.walk(path):
                    dirs[:]=sorted(d for d in dirs if not ignored(os.path.join(root,d)))
                    for f in sorted(files):
                        p=norm(os.path.join(root,f))
