class Preprocessor:
    def __init__(self,options,reporter):
        self.o=options;self.r=reporter;self.sources=reporter.sources
    def read(self,path):
        path=norm(path)
        if path not in self.sources:
            try: self.sources[path]=open(path,errors='replace').read()
            except OSError: return ''
        return self.sources[path]
    def configurations(self,path):
        text=self.read(path)
        definitions={}
        for d in self.o.defines:
            key,eq,value=d.partition('=');definitions[key]=value if eq else '1'
        hidden=set(self.o.undefines)
        local=set(re.findall(r'^\s*#\s*define\s+(\w+)',text,re.M))
        symbols=[]
        for line in text.splitlines():
            m=re.match(r'\s*#\s*(?:ifn?def|if|elif)\s+(.*)',line)
            if m:
                expr=m[1]
                for s in re.findall(r'\b[A-Za-z_]\w*\b',expr):
                    if s not in {'defined','true','false'}|set(definitions)|hidden|local and s not in symbols: symbols.append(s)
        if definitions and not self.o.flag('force') and self.o.max_configs==12: symbols=[]
        combos=[{}]
        for s in sorted(symbols):
            combos += [dict(c,**{s:s}) for c in combos[:]]
            if len(combos)>64: break
        combos=combos[:self.o.max_configs]
        results=[]
        for c in combos:
            defs=dict(definitions,**c)
            conf=';'.join(k+'='+v for k,v in sorted(defs.items()))
            results.append((conf,defs))
        return results
