        def blank(m): return ''.join('\n' if c=='\n' else ' ' for c in m[0])
        clean=re.sub(r'/\*[\s\S]*?\*/|//[^\n]*',blank,source)
        for lineno,line in enumerate(clean.splitlines(),1):
            directive=re.match(r'\s*#\s*(\w+)(.*)',line)
            if directive:
