                        msg='Include file: '+('<'+name+'>' if system else '"'+name+'"')+' not found.'
                        if system: msg+=' Please note: Standard library headers do not need to be provided to get proper results.'
                        self.r.add(Diagnostic('missingIncludeSystem' if system else 'missingInclude','information',msg,Location(path,lineno,line.index('#')+2),file0=path))
