    def condition(self,source,macros):
        source=re.sub(r'defined\s*(?:\(\s*(\w+)\s*\)|(\w+))',lambda m:'1' if (m[1] or m[2]) in macros else '0',source)
        source=re.sub(r'\b[A-Za-z_]\w*\b',lambda m:macros[m[0]][1] if m[0] in macros and macros[m[0]][1]!=m[0] else '0',source)
