    def printable(self,tokens):
        if not tokens: return '\n'
        outtext='';line=1;lastfile=tokens[0].file;started=False
        for t in tokens:
            if t.file!=lastfile:
                if started: outtext+='\n'
                outtext+='#file "'+t.file+'"\n';lastfile=t.file;line=1;started=False
            if t.line>line:
                outtext+='\n'*(t.line-line);line=t.line;started=False
            if started: outtext+=' '
            if t.macro: outtext+=' '
            outtext+=t.text;started=True
        return outtext+'\n'

@dataclass
