                result.append(t);continue
            params,body=macros[t.text]
            if params is None:
                if body==t.text: result.append(t);continue
                ts=tokenize(body,t.file)
                for x in ts: x.line=t.line;x.col=t.col;x.macro=True
                result.extend(self.expand(ts,{k:v for k,v in macros.items() if k!=t.text},depth+1))
