                outtext+='#file "'+t.file+'"\n';lastfile=t.file;line=1;started=False
            if t.line>line:
                outtext+='\n'*(t.line-line);line=t.line;started=False
            if started: outtext+=' '
            if t.macro: outtext+=' '
            outtext+=t.text;started=True
        return outtext+'\n'

@dataclass
class Function:
    name: Token
    start: int
    end: int
