"""Executable entry point and analysis orchestration."""
import json
import os
import re
import sys
import xml.etree.ElementTree as ET
from options import Options, SHARE, out, fail, norm, xml_error
from messages import HELP, DOC, ERRORLIST
from reporting import Reporter, Diagnostic, Location, checker_names, escape
from analysis_engine import Preprocessor, Analyzer, unused_functions


def load_global_configuration(options,args):
    debug='--debug-lookup' in args
    text=None;path=''
    for path in [os.path.join(SHARE,'cppcheck.cfg'),os.path.join(options.bindir,'cppcheck.cfg')]:
        if debug: out("looking for '%s'" % path)
        try:
            text=open(path,errors='replace').read();break
        except OSError: pass
    if text is None:
        if debug: out('no configuration found')
        return
    try: config=json.loads(text)
    except ValueError:
        out('not a valid JSON');raise SystemExit(1)
    if not isinstance(config,dict): return
    if isinstance(config.get('addons'),list):
        options.addons.extend(a for a in config['addons'] if isinstance(a,str))


def load_addons(options):
    for addon in options.addons:
        path=addon
        if addon.endswith('.json'):
            try: text=open(addon,errors='replace').read()
            except OSError:
                out('Failed to open '+addon);raise SystemExit(1)
            try: obj=json.loads(text)
            except ValueError:
                out('Failed to parse '+addon);raise SystemExit(1)
            if isinstance(obj,dict): path=obj.get('script','')
            if not path: continue
        name=path if path.endswith('.py') else path+'.py'
        paths=[name,os.path.join(options.bindir,name),os.path.join(options.bindir,'addons',name),os.path.join(SHARE,'addons',name)]
        if not any(os.path.isfile(p) for p in paths):
            out('Did not find addon '+name);raise SystemExit(1)


def dump_tokens(path,tokens,options):
    try:
        with open(path+'.dump','w') as f:
            f.write('<?xml version="1.0"?>\n<dumps language="'+('c' if path.endswith('.c') else 'cpp')+'">\n')
            f.write('  <platform name="'+escape(options.platform)+'" char_bit="8" short_bit="16" int_bit="32" long_bit="64" long_long_bit="64" pointer_bit="64"/>\n')
            f.write('  <rawtokens>\n    <file index="0" name="'+escape(path)+'"/>\n')
            for t in tokens:
                f.write('    <tok fileIndex="0" linenr="%d" column="%d" str="%s"/>\n' % (t.line,t.col,escape(t.text)))
            f.write('  </rawtokens>\n  <suppressions/>\n  <dump cfg="">\n    <tokenlist/>\n    <scopes/>\n    <variables/>\n    <valueflow/>\n  </dump>\n</dumps>\n')
    except OSError: pass


def analyze(options,files):
    sources={};reporter=Reporter(options,sources);pre=Preprocessor(options,reporter)
    all_functions=[];all_tokens=[]
    sizes=[]
    for p,args in files:
        try: sizes.append(os.path.getsize(p))
        except OSError: sizes.append(0)
    total=sum(sizes);done=0
    for index,(path,commands) in enumerate(files):
        cpp=options.language=='c++' or not options.language and not path.endswith('.c')
        display=options.display_path(path)
        if not options.flag('quiet') and not options.flag('preprocess'):
            out('Checking '+display+' ...')
            if options.flag('verbose'):
                defs=[]
                for d in options.defines:
                    if d: defs.append(d if '=' in d else d+'=1')
                out('Defines:'+';'.join(defs))
                out('Undefines:'+''.join(' '+u for u in sorted(options.undefines) if u))
                out('Includes:'+''.join(' -I'+p.rstrip('/')+'/' for p in options.includes if os.path.isdir(p)))
                out('Platform:'+options.platform)
        if options.clang:
            language='c++' if cpp else 'c'
            cmd=options.clang+' -fsyntax-only -Xclang -ast-dump -fno-color-diagnostics -x '+language+' '+path+' 2>&1'
            sys.stderr.write("Failed to execute '%s' - (exitcode: 127 / output: sh: 1: %s: not found\n)\n" % (cmd,options.clang))
            reporter.checkers.update(checker_names(options,cpp,True))
        else:
            configs=pre.configurations(path)
            seen_tokens=set()
            for conf,defines in configs:
                if conf and not options.flag('quiet') and not options.flag('preprocess'):
                    out('Checking '+display+': '+conf+'...')
                tokens=[]
                for inc in options.include_files:
                    if os.path.isfile(inc): tokens.extend(pre.process(inc,defines))
                tokens.extend(pre.process(path,defines))
                fingerprint=tuple(t.text for t in tokens)
                if fingerprint in seen_tokens and not options.flag('preprocess'): continue
                seen_tokens.add(fingerprint)
                if options.flag('preprocess'):
                    sys.stdout.write(pre.printable(tokens))
                    reporter.checkers.update(checker_names(options,cpp,True))
                elif options.flag('check-config'):
                    reporter.checkers.update(checker_names(options,cpp,True))
                else:
                    analyzer=Analyzer(options,reporter,path,tokens,conf)
                    functions=analyzer.run()
                    all_functions.append((path,functions,tokens));all_tokens.append(tokens)
                    if options.flag('check-library'):
                        known=set()
                        for root in options.library_roots:
                            for x in root.findall('function'): known.update(x.get('name','').split(','))
                        defs={f.name.text for _,fs,_ in all_functions for f in fs}
                        for i,t in enumerate(tokens[:-1]):
                            if tokens[i+1].text=='(' and re.fullmatch(r'[A-Za-z_]\w*',t.text) and t.text not in defs|known|{'if','while','for','switch','return','sizeof','alignof','decltype','catch','assert'}:
