                    if options.flag('dump'): dump_tokens(path,tokens,options)
        done+=sizes[index]
        if len(files)>1 and not options.flag('quiet') and not options.flag('preprocess'):
            percent=int(done*100/total) if total else int((index+1)*100/len(files))
            out('%d/%d files checked %d%% done' % (index+1,len(files),percent))
    if 'unusedFunction' in options.enabled and (options.jobs==1 or options.build_dir) and not options.flag('check-config') and not options.flag('preprocess'):
        unused_functions(all_functions,all_tokens,reporter)
    result=reporter.finish()
    return result


def main():
    try:
        args=sys.argv[1:]
        options=Options(os.path.dirname(os.path.abspath(sys.argv[0])))
        load_global_configuration(options,args)
        if not args:
            sys.stdout.write(HELP);return
        for a in args:
            if a in ('--help','-h','--version','--doc','--errorlist'):
                sys.stdout.write({'--help':HELP,'-h':HELP,'--version':'Cppcheck 2.19 dev\n','--doc':DOC,'--errorlist':ERRORLIST}[a]);return
        options.parse(args)
        options.load_libraries()
        load_addons(options)
        files=options.collect_files()
        raise SystemExit(analyze(options,files) & 255)
    except BrokenPipeError:
        raise SystemExit(0)
